package com.nook.controller; import com.nook.dto.ApiDtos.*; import com.nook.security.CurrentUser; import com.nook.service.NotificationService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/notifications") public class NotificationController {final NotificationService s;public NotificationController(NotificationService s){this.s=s;}@GetMapping PageDto<NotificationDto> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){return s.list(CurrentUser.id(),RequestParameters.page(page),RequestParameters.size(size,100));}@PostMapping("/{id}/read") @ResponseStatus(HttpStatus.NO_CONTENT) void read(@PathVariable UUID id){s.read(CurrentUser.id(),id);}@PostMapping("/devices") @ResponseStatus(HttpStatus.NO_CONTENT) void device(@Valid @RequestBody DeviceTokenRequest x){s.registerDevice(CurrentUser.id(),x.token());}@DeleteMapping("/devices") @ResponseStatus(HttpStatus.NO_CONTENT) void removeDevice(@Valid @RequestBody DeviceTokenRequest x){s.removeDevice(CurrentUser.id(),x.token());}}
